import { useState, useCallback } from 'react';
import type { VersionEntry } from '@cipherbox/core';
import { useAuthStore } from '../../../stores/auth.store';
import { downloadFile, triggerBrowserDownload } from '../../../services/download.service';
import { useFolder } from '../../../hooks/useFolder';
import { formatDate, formatBytes } from '../../../utils/format';
import { formatDateWithTime } from './DetailsPrimitives';
import { vaultKeyMissingError } from './version-download-guard';

/**
 * Version history component for files with past versions.
 * Shows version entries with download, restore, and delete actions.
 */
export function VersionHistory({
  versions,
  fileName,
  folderKey,
  parentFolderId,
  fileId,
  onRestored,
}: {
  versions: VersionEntry[];
  fileName: string;
  folderKey: Uint8Array;
  parentFolderId: string;
  fileId: string;
  onRestored: () => void;
}) {
  const { restoreVersion, deleteVersion } = useFolder();
  const [confirmingRestore, setConfirmingRestore] = useState<number | null>(null);
  const [confirmingDelete, setConfirmingDelete] = useState<number | null>(null);
  const [loadingAction, setLoadingAction] = useState<string | null>(null);
  const [actionError, setActionError] = useState<string | null>(null);

  const handleDownloadVersion = useCallback(
    async (version: VersionEntry) => {
      const privateKey = useAuthStore.getState().vaultKeypair?.privateKey;
      const keyError = vaultKeyMissingError(privateKey);
      if (keyError || !privateKey) {
        // keyError is non-null exactly when privateKey is missing; the explicit
        // !privateKey also narrows the type for the downloadFile call below.
        setActionError(keyError ?? 'Cannot download: vault key not available');
        return;
      }

=== v1 version-download-guard.ts ===
/**
 * D-14: gate a version download on the presence of the vault private key.
 *
 * Returns a user-visible error message when the key is missing (the caller must
 * surface it and abort), or `null` when the download may proceed. Centralizing
 * this here lets both VersionHistory and its tests exercise the same contract
 * instead of a duplicated inline guard.
 */
export function vaultKeyMissingError(privateKey: Uint8Array | undefined | null): string | null {
  if (!privateKey) {
    return 'Cannot download: vault key not available';
  }
  return null;
}

