1	//! The committed KAT generator for the engine's content-DAG fixtures
2	//! (blueprint/core.md "KAT regime": vectors regenerate only through committed
3	//! generators, never hand-edits). Sibling to core's generator; see
4	//! `crates/engine/tests/kat_content.rs` for why the engine needs its own.
5	//!
6	//! Run from any cwd:
7	//!
8	//! ```text
9	//! cargo run -p cipherbox-engine --example kat_gen
10	//! ```
11	//!
12	//! Accept vectors run the live [`assemble`] over leaves the live framing
13	//! produced. Reject vectors are hand-built root maps, since a valid encoder run
14	//! cannot emit any of them. Every vector is asserted against the live decoder
15	//! before anything is written, so a generator run is itself a self-check.
16	//! Output is deterministic: re-running is byte-identical.
17	
18	use std::collections::BTreeSet;
19	use std::fs;
20	use std::path::Path;
21	
22	use cipherbox_core::codec::{Map, Value, encode};
23	use cipherbox_core::content::{CONTENT_CID_CODEC, compute_cid, encode_content_cid_str, verify_cid};
24	use cipherbox_core::suite::aead::KEY_LEN;
25	use cipherbox_engine::content::{
26	    ContentKey, ContentProfile, DAG_ROOT_CODEC, DagError, ROOT_FORMAT_VERSION, assemble,
27	    decode_root, frame_and_seal,
28	};
29	use cipherbox_engine::entropy::{Entropy, EntropyError};
30	use serde::Serialize;
31	
32	const PROFILE: &str = "cipherbox/v2 engine content-dag";
33	
34	/// A pinned entropy stream: KAT vectors must be byte-reproducible, so the
35	/// generator injects a fixed nonce sequence instead of sampling one.
36	struct PinnedEntropy(u8);
37	
38	impl Entropy for PinnedEntropy {
39	    fn fill(&mut self, out: &mut [u8]) -> Result<(), EntropyError> {
40	        for byte in out.iter_mut() {
41	            *byte = self.0;
42	            self.0 = self.0.wrapping_add(1);
43	        }
44	        Ok(())
45	    }
46	}
47	
48	/// A DAG root the live encoder produced, frozen byte-for-byte.
49	#[derive(Serialize)]
50	#[serde(rename_all = "camelCase")]
51	struct DagRootAcceptVector {
52	    name: String,
53	    chunk_size: u64,
54	    size: u64,
55	    leaf_cids: Vec<String>,
56	    root_block: String,
57	    content_cid: String,
58	    content_cid_str: String,
59	}
60	
61	/// A root block the decoder must refuse, and the verdict it must return.
62	#[derive(Serialize)]
63	#[serde(rename_all = "camelCase")]
64	struct DagRootRejectVector {
65	    name: String,
66	    root_block: String,
67	    check: String,
68	    class: String,
69	}
70	
71	/// The flat-DAG capacity boundary. At this link count the root is megabytes, so
72	/// the leaf list is synthesized by [`capacity_leaves`] rather than committed and
73	/// the frozen outputs are the root's size and its CID.
74	#[derive(Serialize)]
75	#[serde(rename_all = "camelCase")]
76	struct DagCapacityAcceptVector {
77	    name: String,
78	    chunk_size: u64,
79	    leaf_count: u64,
80	    size: u64,
81	    root_block_len: usize,
82	    content_cid: String,
83	}
84	
85	/// One link past the capacity boundary: the encoder must refuse rather than
86	/// emit a root its own reader would reject as over-cap.
87	#[derive(Serialize)]
88	#[serde(rename_all = "camelCase")]
89	struct DagCapacityRejectVector {
90	    name: String,
91	    chunk_size: u64,
92	    leaf_count: u64,
93	    size: u64,
94	    check: String,
95	    class: String,
96	}
97	
98	#[derive(Serialize)]
99	#[serde(rename_all = "camelCase")]
100	struct FileCount {
101	    file: String,
102	    count: usize,
103	}
104	
105	#[derive(Serialize)]
106	#[serde(rename_all = "camelCase")]
107	struct RejectSection {
108	    file: String,
109	    count: usize,
110	    checks: Vec<String>,
111	}
112	
113	#[derive(Serialize)]
114	#[serde(rename_all = "camelCase")]
115	struct ContentSection {
116	    root_format_version: u64,
117	    root_cid_codec: u8,
118	    production_chunk_size: u64,
119	    dag_root_accept: FileCount,
120	    dag_root_reject: RejectSection,
121	    dag_capacity_accept: FileCount,
122	    dag_capacity_reject: RejectSection,
123	}
124	
125	#[derive(Serialize)]
126	#[serde(rename_all = "camelCase")]
127	struct Manifest {
128	    manifest_version: u64,
129	    profile: String,
130	    content: ContentSection,
131	}
132	
133	fn main() {
134	    let kat_dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("kat");
135	    let content_dir = kat_dir.join("vectors").join("content");
136	    fs::create_dir_all(&content_dir)
137	        .unwrap_or_else(|e| panic!("create {}: {e}", content_dir.display()));
138	
139	    let root_accept = build_dag_root_accept();
140	    let root_reject = build_dag_root_reject();
141	    // One leaf pool serves the ceiling search and both capacity vectors. The
142	    // bound only has to sit above the ceiling for the search to bracket it.
143	    let pool = capacity_leaves(1 << 17);
144	    let capacity_accept = build_dag_capacity_accept(&pool);
145	    let capacity_reject = build_dag_capacity_reject(&pool, capacity_accept.leaf_count + 1);
146	
147	    write_pretty(&content_dir.join("dag_root_accept.json"), &root_accept);
148	    write_pretty(&content_dir.join("dag_root_reject.json"), &root_reject);
149	    write_pretty(
150	        &content_dir.join("dag_capacity_accept.json"),
151	        &[&capacity_accept],
152	    );
153	    write_pretty(
154	        &content_dir.join("dag_capacity_reject.json"),
155	        &[&capacity_reject],
156	    );
157	
158	    let manifest = Manifest {
159	        manifest_version: 1,
160	        profile: PROFILE.to_string(),
161	        content: ContentSection {
162	            root_format_version: ROOT_FORMAT_VERSION,
163	            root_cid_codec: DAG_ROOT_CODEC,
164	            production_chunk_size: ContentProfile::PRODUCTION.chunk_size() as u64,
165	            dag_root_accept: FileCount {
166	                file: "vectors/content/dag_root_accept.json".to_string(),
167	                count: root_accept.len(),
168	            },
169	            dag_root_reject: RejectSection {
170	                file: "vectors/content/dag_root_reject.json".to_string(),
171	                count: root_reject.len(),
172	                checks: checks_in_surface_order(root_reject.iter().map(|v| v.check.as_str())),
173	            },
174	            dag_capacity_accept: FileCount {
175	                file: "vectors/content/dag_capacity_accept.json".to_string(),
176	                count: 1,
177	            },
178	            dag_capacity_reject: RejectSection {
179	                file: "vectors/content/dag_capacity_reject.json".to_string(),
180	                count: 1,
181	                checks: checks_in_surface_order([capacity_reject.check.as_str()]),
182	            },
183	        },
184	    };
185	    write_pretty(&kat_dir.join("manifest.json"), &manifest);
186	
187	    println!(
188	        "kat_gen: wrote {} accept, {} reject, 2 capacity vectors + manifest.json",
189	        root_accept.len(),
190	        root_reject.len()
191	    );
192	}
193	
194	fn write_pretty<T: Serialize>(path: &Path, value: &T) {
195	    let mut text = serde_json::to_string_pretty(value).expect("serialize JSON");
196	    text.push('\n');
197	    fs::write(path, text).unwrap_or_else(|e| panic!("write {}: {e}", path.display()));
198	}
