200	/// The distinct checks in declaration order, asserting each comes from
201	/// [`DagError::CHECKS`] (a reject vector can never name an off-surface check).
202	fn checks_in_surface_order<'a>(present: impl IntoIterator<Item = &'a str>) -> Vec<String> {
203	    let present: BTreeSet<&str> = present.into_iter().collect();
204	    let checks: Vec<String> = DagError::CHECKS
205	        .iter()
206	        .filter(|c| present.contains(*c))
207	        .map(|c| (*c).to_string())
208	        .collect();
209	    assert_eq!(
210	        checks.len(),
211	        present.len(),
212	        "every reject-vector check must come from the DAG error surface"
213	    );
214	    checks
215	}
