1	//! The platform-neutral vfs operation core: one implementation of every
2	//! filesystem operation, over the engine facade and nothing else
3	//! (blueprint/desktop.md "The FS core and host adapters").
4	//!
5	//! It is a projection, not a second brain. Reads render the facade's snapshot
6	//! (with the pending-op overlay already applied) and never wait on the
7	//! network; mutations become facade intent ops. No keys, no publish
8	//! machinery, no freshness policy — those decisions all happened below the
9	//! facade.
10	
11	use std::collections::BTreeSet;
12	
13	use cipherbox_engine::seams::SeamTypes;
14	use cipherbox_engine::{
15	    Command, Engine, EngineView, NodeAttrs, NodeId, NodeKind, StatFs, StreamHandle,
16	};
17	
18	use zeroize::Zeroizing;
19	
20	use crate::adapter::{CacheTtls, HostAdapter, Invalidation};
21	use crate::cache::{CacheBudget, ChunkCache, grow_wiping};
22	use crate::error::VfsError;
23	use crate::handle::{Access, HandleId, HandleTable, OpenFile};
24	use crate::inode::{InodeTable, ROOT_INO};
25	use crate::name::{is_emittable, is_platform_junk, validate_name};
26	
27	/// A node as the kernel sees it.
28	#[derive(Debug, Clone, PartialEq, Eq)]
29	pub struct Attributes {
30	    /// The session's inode number for the node.
31	    pub ino: u64,
32	    /// The engine's stable node id.
33	    pub node: NodeId,
34	    /// File or folder.
35	    pub kind: NodeKind,
36	    /// Plaintext size in bytes, `None` until the content plane projects one.
37	    /// Never collapsed to zero: a kernel that believes `st_size == 0` stops
38	    /// reading at byte zero, and `cp` writes an empty copy of a real file.
39	    pub size: Option<u64>,
40	    /// Modification time in Unix millis, once projected.
41	    pub mtime_millis: Option<u64>,
42	}
43	
44	/// One entry in a directory listing.
45	#[derive(Debug, Clone, PartialEq, Eq)]
46	pub struct DirEntry {
47	    /// The session's inode number for the child.
48	    pub ino: u64,
49	    /// The child's name, as entered.
50	    pub name: String,
51	    /// File or folder.
52	    pub kind: NodeKind,
53	}
54	
55	/// The operation core for one mount session: the engine it projects, the host
56	/// adapter it pushes invalidation to, and the session's inode and handle maps.
57	pub struct OperationCore<T: SeamTypes, A: HostAdapter> {
58	    engine: Engine<T>,
59	    adapter: A,
60	    inodes: InodeTable,
61	    handles: HandleTable,
62	    cache: ChunkCache,
63	}
64	
65	impl<T: SeamTypes, A: HostAdapter> OperationCore<T, A> {
66	    /// Mount `engine` behind `adapter`, holding at most `cache`'s worth of
67	    /// plaintext. The engine must already be started.
68	    pub fn new(engine: Engine<T>, adapter: A, cache: CacheBudget) -> Self {
69	        Self {
70	            engine,
71	            adapter,
72	            inodes: InodeTable::new(),
73	            handles: HandleTable::new(),
74	            cache: ChunkCache::new(cache),
75	        }
76	    }
77	
78	    /// Plaintext this mount is holding right now — never above the budget it
79	    /// was mounted with.
80	    pub fn cached_plaintext_bytes(&self) -> usize {
81	        self.cache.retained_bytes()
82	    }
83	
84	    /// The kernel cache lifetimes this mount's adapter earned.
85	    pub fn cache_ttls(&self) -> CacheTtls {
86	        CacheTtls::for_host(&self.adapter.capabilities(), self.engine.profile())
87	    }
88	
89	    /// Resolve a name under a directory.
90	    pub async fn lookup(&mut self, parent: u64, name: &str) -> Result<Attributes, VfsError> {
91	        if !is_emittable(name) {
92	            return Err(VfsError::NotFound);
93	        }
94	        let view = self.render().await?;
95	        let parent_node = self.directory(&view, parent)?;
96	        let meta = view.lookup(parent_node, name).ok_or(VfsError::NotFound)?;
97	        Ok(self.attributes(&meta))
98	    }
99	
100	    /// Read one node's attributes.
101	    pub async fn getattr(&mut self, ino: u64) -> Result<Attributes, VfsError> {
102	        let view = self.render().await?;
103	        let node = self.node_of(ino)?;
104	        let meta = view.attrs(node).ok_or(VfsError::NotFound)?;
105	        Ok(self.attributes(&meta))
106	    }
107	
108	    /// List a directory's children in the engine's deterministic order,
109	    /// hiding platform junk and names no kernel could carry — both classes
110	    /// arrive from other clients, which validate nothing. `.` and `..` are the
111	    /// adapter's to synthesize, along with any offset cookies.
112	    pub async fn readdir(&mut self, ino: u64) -> Result<Vec<DirEntry>, VfsError> {
113	        let view = self.render().await?;
114	        let node = self.directory(&view, ino)?;
115	        let children = view.children(node);
116	        let mut entries = Vec::with_capacity(children.len());
117	        for child in children {
118	            if is_platform_junk(&child.name) || !is_emittable(&child.name) {
119	                continue;
120	            }
121	            entries.push(DirEntry {
122	                ino: self.inodes.ino_for(child.id),
123	                name: child.name,
124	                kind: child.kind,
125	            });
126	        }
127	        Ok(entries)
128	    }
